import{_ as t,o as a,c as r,ae as o}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/core-concepts.md","filePath":"guide/core-concepts.md"}'),i={name:"guide/core-concepts.md"};function s(n,e,l,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>Your identity is an <strong>Ed25519 keypair</strong> derived deterministically from a 24-word BIP-39 mnemonic. There&#39;s no account, no server registration, and no email required.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BIP-39 Mnemonic (24 words, 256-bit entropy)</span></span>
<span class="line"><span>  └── Ed25519 Seed (32 bytes)</span></span>
<span class="line"><span>       ├── Ed25519 Keypair (signing, identity)</span></span>
<span class="line"><span>       └── Curve25519 Keypair (derived, key exchange)</span></span></code></pre></div><p>Your <strong>public key</strong> is your identity. Your <strong>mnemonic</strong> is your recovery key. The private key is stored in the OS keystore (Keytar on Windows/macOS, encrypted file on Linux).</p><h3 id="handles" tabindex="-1">Handles <a class="header-anchor" href="#handles" aria-label="Permalink to &quot;Handles&quot;">​</a></h3><p>Handles (like <code>@alice</code>) are optional — they&#39;re provided by the <strong>Discovery</strong> extension. Handles are globally unique and registered on a discovery server via challenge-response authentication.</p><h2 id="shares" tabindex="-1">Shares <a class="header-anchor" href="#shares" aria-label="Permalink to &quot;Shares&quot;">​</a></h2><p>A share is a set of files/folders you make available to others. Each share has:</p><ul><li><strong>Name</strong> — Human-readable label</li><li><strong>Visibility</strong> — Who can access it: <ul><li><code>private</code> — Only named recipients (default)</li><li><code>public</code> — Anyone with the magnet link</li><li><code>global</code> — Published to discovery, anyone can find it</li><li><code>link-only</code> — Time-limited share link</li></ul></li><li><strong>Encryption key</strong> — Random 32-byte key, wrapped per-recipient</li><li><strong>Magnet link</strong> — BitTorrent magnet for P2P transfer</li></ul><h2 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h2><p>All shared content is encrypted with <strong>XChaCha20-Poly1305</strong> in 64KB streaming chunks.</p><ol><li>A random 32-byte share key is generated</li><li>For each recipient, the key is wrapped with their Curve25519 public key (<code>crypto_box_seal</code>)</li><li>File contents are encrypted as a secretstream (authenticated, streaming)</li><li>The filename-to-hash manifest is also encrypted (prevents metadata leakage)</li></ol><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Per-share, per-recipient:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>read</code></td><td>View file contents</td></tr><tr><td><code>write</code></td><td>Modify files</td></tr><tr><td><code>delete</code></td><td>Remove files</td></tr><tr><td><code>canShare</code></td><td>Re-share with others</td></tr><tr><td><code>drillDown</code></td><td>Browse subdirectories</td></tr></tbody></table><h2 id="transfers" tabindex="-1">Transfers <a class="header-anchor" href="#transfers" aria-label="Permalink to &quot;Transfers&quot;">​</a></h2><p>Files transfer via <strong>BitTorrent/WebTorrent</strong> protocol:</p><ol><li><strong>LAN</strong> (mDNS discovered) — Direct TCP, fastest</li><li><strong>Direct</strong> (public IP) — WebRTC or TCP</li><li><strong>Relay</strong> (both behind NAT) — TURN server (Pro feature)</li></ol><p>Transfers can be paused, resumed, and cancelled. Progress is tracked per-file.</p><h2 id="pals" tabindex="-1">Pals <a class="header-anchor" href="#pals" aria-label="Permalink to &quot;Pals&quot;">​</a></h2><p>Pals are contacts you share with. A pal is identified by their Ed25519 public key. You can:</p><ul><li>Add pals by handle, public key, or QR code</li><li>Discover pals on your LAN via mDNS</li><li>See online/offline status (requires Discovery extension)</li></ul><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>Groups are named collections of pals. Share with a group to give all members access at once.</p><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h2><p>Three discovery layers, from local to global:</p><ol><li><strong>mDNS</strong> — Automatic LAN discovery (no internet needed)</li><li><strong>Discovery Server</strong> — Handle registration, online presence, offline inbox</li><li><strong>DHT</strong> — Decentralized peer lookup via BitTorrent Mainline DHT (BEP 44)</li></ol><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Capabilities</th></tr></thead><tbody><tr><td><strong>Owner</strong></td><td>Full access. Manages users, shares, settings. Created on first <code>pe init</code>.</td></tr><tr><td><strong>User</strong></td><td>Create shares, chat, manage own pals. Cannot manage other users.</td></tr><tr><td><strong>Guest</strong></td><td>Read-only. Keys in memory only (wiped on exit).</td></tr></tbody></table>`,30)])])}const y=t(i,[["render",s]]);export{u as __pageData,y as default};
